INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (4600093826010129, ARRAY['"[8 marks] Explain and apply The general design procedure in “Basic Considerations in Process Equipment Design”; include the principle, an example and a verification or limitation."'::jsonb, '"[8 marks] Explain and apply Material selection in “Design Consideration”; include the principle, an example and a verification or limitation."'::jsonb, '"[8 marks] Explain and apply Operating conditions in “Pressure Vessels”; include the principle, an example and a verification or limitation."'::jsonb, '"[8 marks] Explain and apply Material of construction in “Reaction Vessels”; include the principle, an example and a verification or limitation."'::jsonb]::jsonb[], ARRAY[]::jsonb[], ARRAY['"Model answer (8 marks)\n\n**Meaning (2):** The general design procedure appears in “Basic Considerations in Process Equipment Design”. Define its purpose, explain the key steps or factors, connect it to Fabrication Techniques, Equipment classification, Power for rotational motion, Basic Considerations in Process Equipment Design, and give an applied example plus a check or limitation.\n\n**Principles/steps (3):** Explain the topic and relate it to Fabrication Techniques, Equipment classification, Power for rotational motion, Basic Considerations in Process Equipment Design.\n\n**Application/example (2):** Apply it to a practical CHEMICAL PROCESS EQUIPMENT DESIGN problem and state the expected result.\n\n**Verification/conclusion (1):** Check the result and state a limitation or risk.\n\nMarking guide: meaning 2; principles 3; application 2; verification 1."'::jsonb, '"Model answer (8 marks)\n\n**Meaning (2):** Material selection appears in “Design Consideration”. Define its purpose, explain the key steps or factors, connect it to Corrosion prevention, Stresses created due to static and dynamic loads, Combined stresses and theories of failure, Fatigue, and give an applied example plus a check or limitation.\n\n**Principles/steps (3):** Explain the topic and relate it to Corrosion prevention, Stresses created due to static and dynamic loads, Combined stresses and theories of failure, Fatigue.\n\n**Application/example (2):** Apply it to a practical CHEMICAL PROCESS EQUIPMENT DESIGN problem and state the expected result.\n\n**Verification/conclusion (1):** Check the result and state a limitation or risk.\n\nMarking guide: meaning 2; principles 3; application 2; verification 1."'::jsonb, '"Model answer (8 marks)\n\n**Meaning (2):** Operating conditions appears in “Pressure Vessels”. Define its purpose, explain the key steps or factors, connect it to Normal conditions, Transient conditions, Pressure vessel code, Selection of material, and give an applied example plus a check or limitation.\n\n**Principles/steps (3):** Explain the topic and relate it to Normal conditions, Transient conditions, Pressure vessel code, Selection of material.\n\n**Application/example (2):** Apply it to a practical CHEMICAL PROCESS EQUIPMENT DESIGN problem and state the expected result.\n\n**Verification/conclusion (1):** Check the result and state a limitation or risk.\n\nMarking guide: meaning 2; principles 3; application 2; verification 1."'::jsonb, '"Model answer (8 marks)\n\n**Meaning (2):** Material of construction appears in “Reaction Vessels”. Define its purpose, explain the key steps or factors, connect it to Classification of reaction vessel, Heating system, Jackets, Coils, and give an applied example plus a check or limitation.\n\n**Principles/steps (3):** Explain the topic and relate it to Classification of reaction vessel, Heating system, Jackets, Coils.\n\n**Application/example (2):** Apply it to a practical CHEMICAL PROCESS EQUIPMENT DESIGN problem and state the expected result.\n\n**Verification/conclusion (1):** Check the result and state a limitation or risk.\n\nMarking guide: meaning 2; principles 3; application 2; verification 1."'::jsonb]::jsonb[]);

-- ENTREPRENEURSHIP DEVELOPMENT | Mid 1 | medium | TestId 460009382604015 | theory
INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (460009382604015, ARRAY['"[8 marks] A practical problem in Entrepreneurship Development requires the behaviour described by a person organizes resources to pursue an opportunity while managing uncertainty and creating value. Explain how What is Entrepreneurship? applies, outline the steps and justify the result."'::jsonb, '"[8 marks] A practical problem in Entrepreneurship Development requires the behaviour described by the syllabus area concerned with Support system. Explain how Support system applies, outline the steps and justify the result."'::jsonb, '"[8 marks] A practical problem in Entrepreneurship Development requires the behaviour described by a person organizes resources to pursue an opportunity while managing uncertainty and creating value. Explain how Classification & Characteristics of Entrepreneur applies, outline the steps and justify the result."'::jsonb, '"[8 marks] A practical problem in Entrepreneurship Development requires the behaviour described by the syllabus area concerned with benefits and drawbacks of entreprenrship. Explain how benefits and drawbacks of entreprenrship applies, outline the steps and justify the result."'::jsonb]::jsonb[], ARRAY[]::jsonb[], ARRAY['"Model answer (8 marks)\n\n**Meaning and purpose (2 marks):** An entrepreneur identifies an opportunity, assembles resources and manages uncertainty to create value. Success depends on customer needs, feasibility, execution, finance and adaptation.\n\n**Principles/steps (3 marks):** Explain the concept in logical order and relate it to Classification & Characteristics of Entrepreneur; benefits and drawbacks of entreprenrship; Creativity and Risk taking.; Business Reforms. State relevant rules, components, assumptions or formulas and how they affect the outcome.\n\n**Application/example (2 marks):** Apply it to a concrete Entrepreneurship Development task. Identify the objective, describe the selected procedure and state the expected result.\n\n**Verification/conclusion (1 mark):** Check the outcome against the objective, note one limitation or error source, and justify the choice.\n\nMarking guide: meaning/purpose 2; principles/steps 3; application/example 2; verification/conclusion 1."'::jsonb, '"Model answer (8 marks)\n\n**Meaning and purpose (2 marks):** Support system is covered under the syllabus unit “Unit 2”. Define the concept, explain its role and main components or steps, connect it to information related to project and support system., Small Scale Business planning and requirements, Different Govt&Institutional Agencies and what are the different Formalities., Statutory Requirements and Agencies., provide a practical course-related example and state one validation check or limitation.\n\n**Principles/steps (3 marks):** Explain the concept in logical order and relate it to information related to project and support system.; Small Scale Business planning and requirements; Different Govt&Institutional Agencies and what are the different Formalities.; Statutory Requirements and Agencies.. State relevant rules, components, assumptions or formulas and how they affect the outcome.\n\n**Application/example (2 marks):** Apply it to a concrete Entrepreneurship Development task. Identify the objective, describe the selected procedure and state the expected result.\n\n**Verification/conclusion (1 mark):** Check the outcome against the objective, note one limitation or error source, and justify the choice.\n\nMarking guide: meaning/purpose 2; principles/steps 3; application/example 2; verification/conclusion 1."'::jsonb, '"Model answer (8 marks)\n\n**Meaning and purpose (2 marks):** An entrepreneur identifies an opportunity, assembles resources and manages uncertainty to create value. Success depends on customer needs, feasibility, execution, finance and adaptation.\n\n**Principles/steps (3 marks):** Explain the concept in logical order and relate it to What is Entrepreneurship?; benefits and drawbacks of entreprenrship; Creativity and Risk taking.; Business Reforms. State relevant rules, components, assumptions or formulas and how they affect the outcome.\n\n**Application/example (2 marks):** Apply it to a concrete Entrepreneurship Development task. Identify the objective, describe the selected procedure and state the expected result.\n\n**Verification/conclusion (1 mark):** Check the outcome against the objective, note one limitation or error source, and justify the choice.\n\nMarking guide: meaning/purpose 2; principles/steps 3; application/example 2; verification/conclusion 1."'::jsonb, '"Model answer (8 marks)\n\n**Meaning and purpose (2 marks):** benefits and drawbacks of entreprenrship is covered under the syllabus unit “Unit 1”. Define the concept, explain its role and main components or steps, connect it to What is Entrepreneurship?, Classification & Characteristics of Entrepreneur, Creativity and Risk taking., Business Reforms, provide a practical course-related example and state one validation check or limitation.\n\n**Principles/steps (3 marks):** Explain the concept in logical order and relate it to What is Entrepreneurship?; Classification & Characteristics of Entrepreneur; Creativity and Risk taking.; Business Reforms. State relevant rules, components, assumptions or formulas and how they affect the outcome.\n\n**Application/example (2 marks):** Apply it to a concrete Entrepreneurship Development task. Identify the objective, describe the selected procedure and state the expected result.\n\n**Verification/conclusion (1 mark):** Check the outcome against the objective, note one limitation or error source, and justify the choice.\n\nMarking guide: meaning/purpose 2; principles/steps 3; application/example 2; verification/conclusion 1."'::jsonb]::jsonb[]);

